mapper.update:
UPDATE account
SET balance = balance + #{amount},
    version = version + 1,
    updated_at = NOW()
WHERE id = #{id}
  AND version = #{version}

mapper.select:
SELECT
    a.*
FROM account a
INNER JOIN customer c ON a.customer_id = c.id
WHERE a.account_no = #{accountNo}
  AND c.rrn_prefix = #{rrnPrefix}

mapper.update:
UPDATE account
SET balance = balance - #{amount},
    version = version + 1,
    updated_at = NOW()
WHERE id = #{id}
  AND version = #{version}
  AND balance >= #{amount}
